const body = $input.first().json.body || {};
// Shortcuts POST only {"focus":"<name>"}; "" = Focus off. No state field.
const focus = String(body.focus ?? '').trim();
const desired = focus === 'Work' ? 'on' : 'off';
return [{ json: { desired, focus, received_at: new Date().toISOString(), source: 'focus' } }];

const event = $('Normalize Focus Event').first().json;
const row = $input.first().json;
const now = Date.now();
const suppressUntil = row.suppress_focus_until ? Date.parse(row.suppress_focus_until) : 0;
if (suppressUntil && now < suppressUntil) {
  return [{ json: {
    skip: true,
    reason: 'suppress_own_focus',
    desired: event.desired,
    focus: event.focus,
    suppress_focus_until: row.suppress_focus_until
  }}];
}

const current = !!row.work_active;
const wantOn = event.desired === 'on';
const need_focus = wantOn ? !current : current;

return [{ json: {
  skip: false,
  desired: event.desired,
  focus: event.focus,
  need_focus,
  shortcut: wantOn ? 'Set Work Focus' : 'Clear Work Focus',
  workspace_id: Number(row.workspace_id || 3825058),
  inpost_project_id: Number(row.inpost_project_id || 215500877),
  received_at: event.received_at,
  focus_pending_desired: '',
  focus_pending_since: null
}}];

const crypto = require('crypto');
const item = $input.first();
const j = item.json;
const secret = String(j.toggl_secret || '');
const headers = j.headers || {};
const sigHeader = String(headers['x-webhook-signature-256'] || headers['X-Webhook-Signature-256'] || '');
let raw = '';
if (item.binary && item.binary.data) {
  const bin = item.binary.data;
  raw = Buffer.from(bin.data, (bin.encoding || 'base64')).toString('utf8');
} else if (typeof j.body === 'string') {
  raw = j.body;
} else if (j.body != null) {
  raw = JSON.stringify(j.body);
}
const expected = 'sha256=' + crypto.createHmac('sha256', secret).update(raw, 'utf8').digest('hex');
let ok = false;
try {
  const a = Buffer.from(expected);
  const b = Buffer.from(sigHeader);
  ok = !!secret && a.length === b.length && crypto.timingSafeEqual(a, b);
} catch (e) { ok = false; }
let parsed = {};
try { parsed = JSON.parse(raw); } catch (e) { parsed = (j.body && typeof j.body === 'object') ? j.body : {}; }
const payload = parsed.payload;
const validation_code = parsed.validation_code || (payload && typeof payload === 'object' ? payload.validation_code : null) || null;
return [{ json: {
  hmac_ok_strict: ok,
  signature: sigHeader,
  raw_len: raw.length,
  event: parsed,
  validation_code,
  is_ping: payload === 'ping' || parsed.payload === 'ping',
  expected_callback: j.expected_callback,
  url_callback: parsed.url_callback || ''
} }];

const event = $input.first().json.event || {};
const action = String(event.metadata?.action || event.action || '').toLowerCase();
let payload = event.payload;
if (typeof payload === 'string') {
  try { payload = JSON.parse(payload); } catch (e) { payload = {}; }
}
payload = payload && typeof payload === 'object' ? payload : {};
const projectId = Number(payload.project_id || 0);
const inpostId = 215500877;
const workspaceId = Number(payload.workspace_id || 3825058);
const duration = Number(payload.duration);
const isRunning = duration < 0 || (!payload.stop && payload.start);
const isInPost = projectId === inpostId;
const deleted = action.includes('delet') || !!payload.server_deleted_at;
let workDesired = null;
if (isInPost && !deleted && isRunning) workDesired = true;
if (isInPost && (deleted || (!isRunning && payload.stop))) workDesired = false;
return [{ json: {
  action, projectId, inpostId, workspaceId, isRunning, isInPost, deleted,
  workDesired, relevant: workDesired !== null,
  entryId: String(payload.id || ''),
  description: payload.description || '',
  received_at: new Date().toISOString(),
  source: 'toggl'
} }];

const evt = $('Parse Toggl Event').first().json;
const row = $input.first().json;
const now = Date.now();
const suppressUntil = row.suppress_toggl_until ? Date.parse(row.suppress_toggl_until) : 0;
if (suppressUntil && now < suppressUntil) {
  return [{ json: { skip: true, reason: 'suppress_own_toggl', workDesired: evt.workDesired } }];
}
const desired = !!evt.workDesired;
const current = !!row.work_active;
const need_focus = desired !== current;
// Clear leftover pending fields; only SSH Focus when state actually changes
return [{ json: {
  skip: false,
  desired,
  need_focus,
  shortcut: desired ? 'Set Work Focus' : 'Clear Work Focus',
  focus_pending_desired: '',
  focus_pending_since: null,
  work_active: desired,
  last_source: 'toggl',
  last_event_at: evt.received_at,
  last_inpost_entry_id: evt.entryId || row.last_inpost_entry_id,
  suppress_focus_until: need_focus ? new Date(now + 120000).toISOString() : (row.suppress_focus_until || null),
  notes: `toggl set work=${desired} entry=${evt.entryId} need_focus=${need_focus}`
} }];

const row = $input.first().json;
return [{ json: {
  rowId: row.id,
  work_active: !!row.work_active,
  workspace_id: Number(row.workspace_id || 3825058),
  inpost_project_id: Number(row.inpost_project_id || 215500877),
  last_inpost_entry_id: row.last_inpost_entry_id || '',
  suppress_focus_until: row.suppress_focus_until,
  suppress_toggl_until: row.suppress_toggl_until
} }];

const plan = $('Decide Schedule Actions').first().json;
const cur = $input.first().json;
const entry = cur && cur.id ? cur : null;
const has = !!(entry && entry.id);
const isInPost = has && Number(entry.project_id || 0) === Number(plan.inpost_project_id);
const known = !!plan.work_active;
if (isInPost === known) return [{ json: { skip: true } }];
// Drift detected (missed webhook)
const desired = isInPost;
return [{ json: {
  skip: false,
  desired,
  shortcut: desired ? 'Set Work Focus' : 'Clear Work Focus',
  work_active: desired,
  last_inpost_entry_id: desired ? String(entry.id) : '',
  last_source: 'reconcile',
  last_event_at: new Date().toISOString(),
  suppress_focus_until: new Date(Date.now() + 120000).toISOString(),
  notes: `reconcile drift work=${desired}`
} }];

const webhook = $('Toggl Webhook').first();
const secretRow = $input.first().json;
const out = Object.assign({}, webhook.json, { toggl_secret: secretRow.value, expected_callback: 'https://n8n.dominiksiejak.pl/webhook/toggl-time-entry' });
const item = { json: out };
if (webhook.binary) item.binary = webhook.binary;
return [item];

const route = $('Route Focus Event').first().json;
const row = $('Get Controller (Focus)').first().json;
const cur = $input.first().json;
const entry = cur && cur.id ? cur : (cur.data || null);
const has = !!(entry && entry.id);
const workspace_id = Number(route.workspace_id || 3825058);
const inpost_project_id = Number(route.inpost_project_id || 215500877);
const projectId = has ? Number(entry.project_id || 0) : 0;
const isInPost = has && projectId === inpost_project_id;
const need_stop = has && !isInPost;
const need_start = !isInPost;
return [{ json: {
  desired: true,
  need_stop,
  need_start,
  need_focus: !!route.need_focus,
  shortcut: 'Set Work Focus',
  stop_id: need_stop ? entry.id : null,
  stop_wid: need_stop ? (entry.workspace_id || workspace_id) : null,
  workspace_id,
  inpost_project_id,
  focus: route.focus,
  suppress_until: new Date(Date.now() + 120000).toISOString(),
  suppress_focus_until: route.need_focus
    ? new Date(Date.now() + 120000).toISOString()
    : (row.suppress_focus_until || null),
  notes: `focus immediate on stop=${need_stop} start=${need_start} need_focus=${!!route.need_focus}`
}}];

const route = $('Route Focus Event').first().json;
const row = $('Get Controller (Focus)').first().json;
const cur = $input.first().json;
const entry = cur && cur.id ? cur : (cur.data || null);
const has = !!(entry && entry.id);
const workspace_id = Number(route.workspace_id || 3825058);
const inpost_project_id = Number(route.inpost_project_id || 215500877);
const projectId = has ? Number(entry.project_id || 0) : 0;
const isInPost = has && projectId === inpost_project_id;
const need_stop = isInPost;
return [{ json: {
  desired: false,
  need_stop,
  need_focus: !!route.need_focus,
  shortcut: 'Clear Work Focus',
  stop_id: need_stop ? entry.id : null,
  stop_wid: need_stop ? (entry.workspace_id || workspace_id) : null,
  workspace_id,
  inpost_project_id,
  focus: route.focus,
  suppress_until: need_stop
    ? new Date(Date.now() + 120000).toISOString()
    : (row.suppress_toggl_until || null),
  suppress_focus_until: route.need_focus
    ? new Date(Date.now() + 120000).toISOString()
    : (row.suppress_focus_until || null),
  notes: `focus immediate off stop=${need_stop} need_focus=${!!route.need_focus}`
}}];
